    if isTable(self._data.unlock) then
        --[[
        "unlock": [{
				"targetType": "4",
				"targetId": null,
				"targetNum": "102140"
			}],
        --]]
        local unlock = table.takeFirst(self._data.unlock)
        local isUnlock = GameUtils.IsUnlockedSingle(unlock.targetType, unlock.targetNum, unlock.targetId)
        if not isUnlock then
            GameUtils.Toast(GameUtils.GetUnlockDescr(checkNumber(unlock.targetType), unlock.targetNum, unlock.targetId))
            return
        end
    end
    UIModule.OpenDialog({ id = Constants.UITypeIds.UIActionEquipCollectionDialog}, {{id = Constants.UITypeIds.UIActivityMainDialog}})
end

